    lines = [str(t)]
    for _ in range(t):
        n = draw(st.integers(1, 6))
        choice = st.sampled_from([
            st.integers(-1000, 1000),
            st.integers(-3, 3),
            st.sampled_from([-1000, 1000, 0, -1, 1]),
        ])
        a = draw(st.lists(choice, min_size=n, max_size=n))
        lines.append(str(n))
        lines.append(" ".join(map(str, a)))
    return "\n".join(lines) + "\n"


