    pos = 0
    if not tok:
        return False
    t = int(tok[pos]); pos += 1
    if not (1 <= t <= 10**4):
        return False
    total = 0
    for _ in range(t):
        if pos >= len(tok):
            return False
        n = int(tok[pos]); pos += 1
        if not (1 <= n <= 2 * 10**5):
            return False
        total += n
        if pos + n > len(tok):
            return False
        a = [int(x) for x in tok[pos:pos + n]]
        pos += n
        if any(abs(x) > 10**3 for x in a):
            return False
    if total > 2 * 10**5:
        return False
    return pos == len(tok)


