from hypothesis import strategies as st


def _parse(inp):
    tok = inp.split()
    t = int(tok[0])
    pos = 1
    tests = []
    for _ in range(t):
        n = int(tok[pos])
        a = [int(x) for x in tok[pos + 1:pos + 1 + n]]
        if len(a) != n:
            raise ValueError("truncated")
        tests.append(a)
        pos += 1 + n
    if pos != len(tok):
        raise ValueError("extra tokens")
    return tests


